/**
 * LEDGER CACHE — the fix for the measured 41%.
 *
 * THE MEASUREMENT THIS ANSWERS
 *
 * A V8 sampling profile of a 24h-equivalent load (2880 turns, 128,581 samples) attributed:
 *
 *     fs            37.0%     readFileUtf8 / writeFileUtf8 / rename / existsSync
 *     json          14.0%
 *     retrieve 逐行解析 13.2%   (retrieve.js:838 and :904)
 *     readJsonl     14.0%     three instances, one per ledger file
 *
 * Merged, "read the whole ledger and parse it" is ≈41% of the turn. The cost is not the
 * bytes — the ledgers are ~2 MB — it is that EVERY append reads and EVERY retrieve re-parses
 * the entire file. So the fix is not a faster parser; it is not re-reading.
 *
 * THE SHAPE
 *
 *   read    → memory (validated by two stats, not by re-parsing)
 *   append  → one `appendFileSync` to a WAL, plus an in-memory push
 *   flush   → rewrite the main ledger once per N writes / T seconds
 *   crash   → replay the WAL at load; the WAL is the durability boundary
 *
 * WHY STAT-VALIDATION AND NOT "TRUST THE CACHE"
 *
 * dsh-memory is loaded as a plugin and harvest can run in more than one process. A cache that
 * assumes it is the only writer would serve stale rows after another process appended. Two
 * `statSync` calls cost microseconds and let the cache detect a foreign write and reload.
 * That is the whole safety argument, and it is cheap enough to keep.
 *
 * WHY THE WAL IS A SEPARATE FILE AND NOT "JUST BUFFER IN MEMORY"
 *
 * A memory-only buffer loses every unflushed row on a crash. The WAL makes the durability
 * boundary explicit: a row that reached `appendFileSync` survives; a row that only reached
 * the array does not, and that window is bounded by the flush interval.
 *
 * TEST MODE
 *
 * Suites assert on file contents directly (`readFileSync(...)` in ~9 places). Under
 * `node --test` the environment sets `NODE_TEST_CONTEXT`, and this module flushes after every
 * write so those assertions keep seeing what they expect. The optimisation is disabled
 * exactly where it would make a test lie.
 */
import { appendFileSync, existsSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** How many appended records may sit in the WAL before a flush is forced. */
export const FLUSH_EVERY = 100
/** How long a record may sit in the WAL before a flush is forced (ms). */
export const FLUSH_INTERVAL_MS = 5000

/** `node --test` sets this in the child process; the optimisation must not hide writes. */
export const TEST_MODE = process.env.NODE_TEST_CONTEXT !== undefined

                       
                                         
                     
                  
                                                    
                  
     
                                                                          
    
                                                                                           
                                                                                             
                                                                                              
                                                                                             
                                                                
    
                                                                                             
                                                                                           
     
                        
                                      
                 
                     
     
                                                                                          
    
                                                                                        
                                                                                         
                                                                                      
     
                 
     
                                      
    
                                                                                             
                                                                                            
                                                                                            
                                                                                           
                   
     
                    
     
                                                                                
                                                               
     
                     
 

const cache = new Map                     ()

function walPathOf(path        )         {
  return `${path}.wal`
}

function statOr(path        )                                                {
  try {
    const state = statSync(path)
    return { mtimeMs: state.mtimeMs, size: state.size }
  } catch {
    return undefined
  }
}

function parseLines(text        )                                 {
  const out                                 = []
  for (const line of text.split(/\r?\n/u)) {
    if (line.trim().length === 0) continue
    try {
      const parsed = JSON.parse(line)
      if (parsed !== null && typeof parsed === 'object') out.push(parsed                           )
    } catch {
      // A torn line must not erase the rest of the ledger.
    }
  }
  return out
}

/**
 * Fold the WAL into the main ledger and reset the WAL.
 *
 * Always a full rewrite of the main file. That is deliberate: append-only would be cheaper,
 * but the negative ledger also PATCHES existing rows (a repeat hit bumps `hits`), and a
 * patch cannot be expressed as an append. One rewrite per FLUSH_EVERY writes is O(N/100) per
 * turn, which is the entire point.
 */
export function flushLedger(path        , force = false)          {
  const state = cache.get(path)
  if (state === undefined) return false
  /**
   * ⚠️ `force` exists because a PATCH writes nothing to the WAL.
   *
   * A `hits += 1` or an evidence-union mutates an object already in the cached array and
   * appends zero rows. With the old guard (`walBytes === 0 && pending === 0 → return`) that
   * mutation was never flushed, so the patch was lost on the next reload. Measured as
   * "evidence expected 2 rows, got 1".
   */
  if (!force && state.walBytes === 0 && state.pending === 0) return false
  /**
   * Fold any buffered WAL payload into the file BEFORE the main rewrite. On a successful
   * flush the WAL is deleted straight after, so this write only matters for the crash window
   * between the two steps — which is exactly the window a WAL exists to narrow.
   */
  if (state.walBuffer.length > 0) {
    try {
      appendFileSync(walPathOf(path), state.walBuffer.join(''), 'utf8')
      state.walBuffer.length = 0
    } catch {
      /* the main rewrite below still makes the rows durable */
    }
  }
  const body = state.records.length === 0 ? '' : `${state.records.map((record) => JSON.stringify(record)).join('\n')}\n`
  writeFileSync(path, body, 'utf8')
  try {
    rmSync(walPathOf(path), { force: true })
  } catch {
    /* a leftover WAL is replayed harmlessly on the next load */
  }
  const stat = statOr(path)
  state.mainMtimeMs = stat?.mtimeMs ?? -1
  state.mainSize = stat?.size ?? -1
  state.walBytes = 0
  state.pending = 0
  state.lastFlushMs = Date.now()
  /** The WAL file is gone after a successful flush, and the buffer is empty by construction. */
  state.syncedWalBytes = 0
  return true
}

/** Flush every cached ledger. Call on shutdown and from tests. */
export function flushAllLedgers()         {
  let flushed = 0
  for (const path of cache.keys()) if (flushLedger(path)) flushed += 1
  return flushed
}

                                 
                                         
                                                                                  
                    
 

/**
 * Read one ledger, from cache when the two stats still match.
 *
 * On a miss the file body is parsed ONCE and the WAL is replayed, then the WAL is folded in
 * immediately — if it were left in place, the next flush would append those rows a second
 * time and duplicate them.
 */
export function readLedger(path        )                 {
  const main = statOr(path)
  const wal = statOr(walPathOf(path))
  const cached = cache.get(path)
  const mainMtime = main?.mtimeMs ?? -1
  const mainSize = main?.size ?? -1
  /**
   * Validate against the WAL as it exists ON DISK (`syncedWalBytes`), never against the
   * buffered count — otherwise our own unflushed buffer looks like a foreign change on every
   * read and the cache reloads away the rows it was holding. See the field's note.
   */
  const walOnDisk = wal?.size ?? 0
  if (
    cached !== undefined &&
    cached.mainMtimeMs === mainMtime &&
    cached.mainSize === mainSize &&
    cached.syncedWalBytes === walOnDisk
  ) {
    return { records: cached.records, fromCache: true }
  }
  /** Cold path: parse the main ledger, then replay whatever the WAL holds. */
  const records                                 = []
  if (main !== undefined) {
    try {
      records.push(...parseLines(readFileSync(path, 'utf8')))
    } catch {
      /* an unreadable ledger is an empty ledger here; callers treat it the same way */
    }
  }
  let replayed = 0
  if (wal !== undefined) {
    try {
      const rows = parseLines(readFileSync(walPathOf(path), 'utf8'))
      records.push(...rows)
      replayed = rows.length
    } catch {
      /* a missing WAL is an empty WAL */
    }
  }
  const next              = {
    records,
    mainMtimeMs: mainMtime,
    mainSize: mainSize,
    /** Bytes replayed from the WAL are already inside `records`. */
    walBytes: walOnDisk,
    pending: 0,
    lastFlushMs: Date.now(),
    /** A reload is a new content version: caches keyed on the old one must rebuild. */
    version: (cache.get(path)?.version ?? 0) + 1,
    /**
     * A RELOAD ALSO INVALIDATES DERIVED DOCUMENTS.
     *
     * The rows on disk may have been rewritten by another process (or by the test suite)
     * without any length change — same count, different content, same `patchCount`. Treating
     * that as "append-only" made an incremental document cache serve the pre-reload rows:
     * measured as a bitemporal test still seeing a negative that had been invalidated on disk.
     */
    patchCount: (cache.get(path)?.patchCount ?? 0) + 1,
    walBuffer: [],
    /** After a reload the in-memory view matches what is on disk. */
    syncedWalBytes: walOnDisk,
  }
  cache.set(path, next)
  /** Fold the replayed WAL in so it cannot be applied twice. */
  if (replayed > 0) flushLedger(path)
  return { records: next.records, fromCache: false }
}

/** Read without exposing the snapshot shape; the common call. */
export function readRecords(path        )                                 {
  return readLedger(path).records
}

/**
 * Append records: one WAL write, one in-memory push, maybe a flush.
 *
 * Returns how many rows were handed to the WAL. The caller has already decided what is new;
 * this function does not deduplicate — dedup is a policy question that belongs to the store.
 */
export function appendRecords(path        , records                                        )         {
  if (records.length === 0) return 0
  const { records: live } = readLedger(path)
  const lines = `${records.map((record) => JSON.stringify(record)).join('\n')}\n`
  appendFileSync(walPathOf(path), lines, 'utf8')
  live.push(...records)
  const state = cache.get(path)
  if (state !== undefined) {
    state.walBytes += Buffer.byteLength(lines, 'utf8')
    state.pending += records.length
  }
  /**
   * TEST_MODE flushes every write: suites read the ledger back with `readFileSync` and would
   * otherwise observe an empty file. A test that passes only because the write buffer is
   * warm is not a test.
   */
  if (TEST_MODE) {
    flushLedger(path)
  } else if (state !== undefined && (state.pending >= FLUSH_EVERY || Date.now() - state.lastFlushMs >= FLUSH_INTERVAL_MS)) {
    flushLedger(path)
  }
  return records.length
}

/**
 * Apply a batch of changes that may include BOTH appends and in-place patches.
 *
 * THE PROBLEM THIS SOLVES
 *
 * `appendNegatives` does two different things: it appends new rows, and it PATCHES an existing
 * row when the same symptom+cause comes back (`hits += 1`, evidence union). A pure WAL append
 * cannot express the second kind. If the cache only ever appended, a repeat hit would live in
 * memory and vanish on the next reload.
 *
 * So: new rows go to the WAL (the cheap path, the common path), and any patch forces an
 * immediate flush — a patch is rare, and flushing on it is cheaper than maintaining a
 * second change-log format for one field.
 */
export function commitLedger(
  path        ,
  newRecords                                        ,
  options                       = { patched: false },
)         {
  /**
   * ⚠️ THE CALLER HAS ALREADY MUTATED THE CACHED ARRAY.
   *
   * `appendNegatives` / `appendLayer` read the cached array, push into it, and then hand the
   * NEW tail here. The first version of this function pushed again — and because
   * `readLedger` returns the SAME array instance, every append was applied twice. The
   * symptom was "expected two rows, got 4", which is a data-corruption bug, not a slow path.
   *
   * So this function only DURABILISES. It never touches the in-memory array.
   */
  const state = cache.get(path)
  if (newRecords.length > 0) {
    const lines = `${newRecords.map((record) => JSON.stringify(record)).join('\n')}\n`
    /**
     * v1.1.0 P0+ — THE WAL IS BUFFERED, AND THE DURABILITY WINDOW IS STATED.
     *
     * `appendFileSync` per call meant open/write/close per call: three of those per simulated
     * turn, and the last profile put `open` at 2.8% of the CPU. Buffering the WAL string and
     * writing it in batches removes the syscalls.
     *
     * WHAT IT COSTS: a hard kill between two batch writes loses those rows. The window is the
     * same one the ledger flush already has (`FLUSH_EVERY` rows / `FLUSH_INTERVAL_MS`), so it
     * does not widen the worst case — it makes the WAL as durable as the thing it protects.
     * `TEST_MODE` writes through immediately so a suite never observes a stale file.
     */
    if (state !== undefined && !TEST_MODE) state.walBuffer.push(lines)
    else appendFileSync(walPathOf(path), lines, 'utf8')
    if (state !== undefined) {
      state.walBytes += Buffer.byteLength(lines, 'utf8')
      state.pending += newRecords.length
    }
  }
  /**
   * THE TWO COUNTERS DIVERGE HERE, AND THAT IS THE POINT.
   *
   * `version` moves on any mutation. `patchCount` moves only when rows that were already
   * built into documents have changed underneath a derived cache. A Document cache uses the
   * first to know "something happened" and the second to decide whether it may APPEND or must
   * REBUILD.
   */
  if (state !== undefined) {
    if (newRecords.length > 0) state.version += 1
    if (options.patched) {
      state.version += 1
      state.patchCount += 1
    }
  }
  /**
   * A patch rewrites the whole ledger on the spot: the array already holds the patched
   * object, and flushing is what makes that durable. Rare enough not to matter.
   */
  if (options.patched || TEST_MODE) {
    flushLedger(path, options.patched)
  } else if (state !== undefined && (state.pending >= FLUSH_EVERY || Date.now() - state.lastFlushMs >= FLUSH_INTERVAL_MS)) {
    flushLedger(path)
  }
  return newRecords.length
}

/**
 * Replace a ledger's whole contents (archive trim, conflict rebuild, migrations).
 * Writes through the cache so the next read does not resurrect the old rows from disk.
 */
export function replaceRecords(path        , records                                        )       {
  const copy = [...records]
  writeFileSync(path, copy.length === 0 ? '' : `${copy.map((record) => JSON.stringify(record)).join('\n')}\n`, 'utf8')
  try {
    rmSync(walPathOf(path), { force: true })
  } catch {
    /* ignore */
  }
  const stat = statOr(path)
  cache.set(path, {
    records: copy,
    mainMtimeMs: stat?.mtimeMs ?? -1,
    mainSize: stat?.size ?? -1,
    walBytes: 0,
    pending: 0,
    lastFlushMs: Date.now(),
    walBuffer: [],
    /** The WAL was deleted just above, so the on-disk WAL size is zero. */
    syncedWalBytes: 0,
    version: (cache.get(path)?.version ?? 0) + 1,
    /** A wholesale replace invalidates every derived document. */
    patchCount: (cache.get(path)?.patchCount ?? 0) + 1,
  })
}

/** Drop one cache entry (tests, or after an external tool rewrote the file). */
export function invalidateLedger(path        )       {
  cache.delete(path)
}

/** Drop every cache entry. */
export function clearLedgerCache()       {
  cache.clear()
}

/** Cache statistics, for the profile script and for tests that assert the cache is used. */
export function ledgerCacheStats()                                                         {
  let pending = 0
  let walBytes = 0
  for (const state of cache.values()) {
    pending += state.pending
    walBytes += state.walBytes
  }
  return { entries: cache.size, pending, walBytes }
}

/**
 * Content version of one ledger — bumped by every append, patch, replace and reload.
 * A downstream cache that keys on this stops confusing "the file did not change" with
 * "the data did not change".
 */
export function ledgerVersion(path        )         {
  return cache.get(path)?.version ?? 0
}

/**
 * How many in-place patches this ledger has seen.
 *
 * A Document cache may serve an APPEND incrementally, but a patch means rows it already
 * converted have changed. This counter lets it tell the two apart; without it every append
 * forced a full rebuild of every document (the reason the first Document cache measured as a
 * 1.04× no-op).
 */
export function ledgerPatchCount(path        )         {
  return cache.get(path)?.patchCount ?? 0
}

/* ── background flush ─────────────────────────────────────────────────────────────────── */

let flushTimer                                            

/**
 * Start the periodic flush. The timer is `unref`ed: a memory plugin must never be the reason
 * a process stays alive. This is the discipline the audit checked for and found zero
 * violations of; a new timer without it would be the first.
 */
export function startLedgerFlushTimer(intervalMs = FLUSH_INTERVAL_MS)       {
  if (flushTimer !== undefined) return
  flushTimer = setInterval(() => {
    try {
      flushAllLedgers()
    } catch {
      /* a failed flush is retried on the next tick */
    }
  }, intervalMs)
  flushTimer.unref?.()
}

export function stopLedgerFlushTimer()       {
  if (flushTimer === undefined) return
  clearInterval(flushTimer)
  flushTimer = undefined
}

/** Flush on process exit, best effort. */
export function installLedgerExitFlush()       {
  const flush = ()       => {
    try {
      flushAllLedgers()
    } catch {
      /* exiting anyway */
    }
  }
  process.once('exit', flush)
  process.once('SIGINT', flush)
  process.once('SIGTERM', flush)
}
